import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.C2TvIV46.js";const m=JSON.parse('{"title":"算術演算","description":"","frontmatter":{},"headers":[],"relativePath":"ja/language/enums/math-operations.md","filePath":"ja/language/enums/math-operations.md"}'),s={name:"ja/language/enums/math-operations.md"};function c(n,e,l,r,i,g){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="算術演算" tabindex="-1">算術演算 <a class="header-anchor" href="#算術演算" aria-label="Permalink to &quot;算術演算&quot;">​</a></h1><p>数値をその場で変更するアクション用の演算子です。オペランドの順序は常に <code>&lt;target&gt; &lt;operation&gt; &lt;value&gt;</code> です（例: <code>action set my_counter add 1</code>）。</p><p><a href="/MegaloEvolved/beta/docs/ja/language/actions/set"><code>set</code></a>、<a href="/MegaloEvolved/beta/docs/ja/language/actions/set-score"><code>set_score</code></a>、<a href="/MegaloEvolved/beta/docs/ja/language/actions/player-adjust-money"><code>player_adjust_money</code></a>、<a href="/MegaloEvolved/beta/docs/ja/language/actions/adjust-grenades"><code>adjust_grenades</code></a>、および <a href="/MegaloEvolved/beta/docs/ja/language/actions/object-adjust-health"><code>object_adjust_*</code></a> のヘルス／シールド系アクションで使います。</p><p>値は <a href="https://github.com/Blam-Network/blf/blob/main/blf-ts/src/blam/haloreach_mcc/v_untracked_25_08_16_1352/game/megalogamengine/megalogamengine_actions.ts" target="_blank" rel="noreferrer">@blamnetwork/blf</a> の <code>e_math_operation</code> と一致します。Reach のスクリプトは演算子を単語で書きます（<code>add</code>、<code>set_to</code>、<code>multiply</code>）。デコンパイラは代入風の記号（<code>+=</code>、<code>=</code>、<code>*=</code>）を出力します。どちらの形式も受け付けます。</p><table tabindex="0"><thead><tr><th>演算子</th><th>記号</th><th>効果</th><th>追加バージョン</th></tr></thead><tbody><tr><td><code>add</code></td><td><code>+=</code></td><td>現在値に加算</td><td><a href="/MegaloEvolved/beta/docs/ja/versions/49/">49</a></td></tr><tr><td><code>subtract</code></td><td><code>-=</code></td><td>現在値から減算</td><td><a href="/MegaloEvolved/beta/docs/ja/versions/49/">49</a></td></tr><tr><td><code>multiply</code></td><td><code>*=</code></td><td>現在値に乗算</td><td><a href="/MegaloEvolved/beta/docs/ja/versions/49/">49</a></td></tr><tr><td><code>divide</code></td><td><code>/=</code></td><td>現在値を除算</td><td><a href="/MegaloEvolved/beta/docs/ja/versions/49/">49</a></td></tr><tr><td><code>set_to</code></td><td><code>=</code></td><td>現在値を代入（置き換え）</td><td><a href="/MegaloEvolved/beta/docs/ja/versions/49/">49</a></td></tr><tr><td><code>modulo</code></td><td><code>%=</code></td><td>除算の余りで置き換え</td><td><a href="/MegaloEvolved/beta/docs/ja/versions/49/">49</a></td></tr><tr><td><code>and</code></td><td><code>&amp;=</code></td><td>オペランドとのビット AND</td><td><a href="/MegaloEvolved/beta/docs/ja/versions/49/">49</a></td></tr><tr><td><code>or</code></td><td><code>|=</code></td><td>オペランドとのビット OR</td><td><a href="/MegaloEvolved/beta/docs/ja/versions/49/">49</a></td></tr><tr><td><code>xor</code></td><td><code>^=</code></td><td>オペランドとのビット XOR</td><td><a href="/MegaloEvolved/beta/docs/ja/versions/73/">73</a></td></tr><tr><td><code>not</code></td><td><code>~=</code></td><td>ビット NOT マージ（<code>a not b</code> → <code>a &amp;= ~b</code>）</td><td><a href="/MegaloEvolved/beta/docs/ja/versions/73/">73</a></td></tr><tr><td><code>abs</code></td><td>—</td><td>オペランドの絶対値を設定</td><td><a href="/MegaloEvolved/beta/docs/ja/versions/73/">73</a></td></tr><tr><td><code>lshift</code></td><td><code>&lt;&lt;</code></td><td>左ビットシフトして代入</td><td><a href="/MegaloEvolved/beta/docs/ja/versions/107-mcc/">107 (MCC)</a></td></tr><tr><td><code>rshift</code></td><td><code>&gt;&gt;</code></td><td>右ビットシフトして代入</td><td><a href="/MegaloEvolved/beta/docs/ja/versions/107-mcc/">107 (MCC)</a></td></tr></tbody></table><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><p>Omaha Alpha（ビルド <strong>49</strong>）は演算を 3 ビットで格納するため、上記のうち最初の 8 演算子のみエンコード可能です。Omaha Delta（<strong>73</strong>）はフィールドを 4 ビットに広げ、XOR・NOT・絶対値代入を追加します。Reach MCC（<strong>107 MCC</strong>）はビットシフト演算子を追加します。MCC ビルドでは <code>abs</code> の enum インデックスは <strong>12</strong> です（Xbox 360 TU1 ではインデックス <strong>10</strong>）。</p><p>@blamnetwork/megalo は単語名と記号の両方を受け付けます。レガシー blf の enum 名（<code>multiply_by</code>、<code>set_to_absolute</code> など）も、古いスクリプトのパース時には引き続き受け付けます。</p><h2 id="例" tabindex="-1">例 <a class="header-anchor" href="#例" aria-label="Permalink to &quot;例&quot;">​</a></h2><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action set my_counter set_to </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">action set my_counter add </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">action set temp modulo </span><span class="megalo-number">5</span></span>
<span class="line"><span class="megalo-text">action set_score add kill_points player killing_player</span></span>
<span class="line"><span class="megalo-text">action object_adjust_shield current_player set_to </span><span class="megalo-number">100</span></span></code></pre></div>`,10)])])}const h=t(s,[["render",c]]);export{m as __pageData,h as default};
